.carousel {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: component.$carousel-gap;

  &__banner {
    width: 100%;

    > * {
      width: 100%;
      height: 100%;
    }

    img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      display: block;
    }
  }

  &__thumbs {
    display: flex;
    gap: component.$carousel-thumbs-gap;
    overflow-x: auto;
    padding-block: 2px calc(var(--carousel-gap, 8px) / 2);
    scroll-snap-type: x mandatory;
    scrollbar-width: thin;
  }

  &__thumb {
    // Transparent until chosen, so selecting a thumbnail changes its colour
    // rather than its size — a border that appears on selection shifts the
    // whole strip by two pixels.
    border: component.$carousel-thumb-border-width solid transparent;
    padding: 0;
    cursor: pointer;
    opacity: 1;
    scroll-snap-align: start;
    font: inherit;
    transition:
      opacity 160ms ease,
      border-color 160ms ease,
      transform 160ms ease,
      box-shadow 160ms ease;
    width: 80px;
    flex-shrink: 0;

    > * {
      width: 100%;
      height: 100%;
    }

    img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      display: block;
    }

    &:hover {
      opacity: 1;
      transform: translateY(-1px);
    }

    &--active {
      opacity: 1;
      border-color: var(--app-border-selected);
      box-shadow: var(--app-shadow-inset);
    }
  }
}

.checkbox {
  align-items: center;
  color: var(--app-field-color);
  display: inline-flex;
  height: component.$checkbox-height;
  justify-content: center;
  line-height: 1;
  mix-blend-mode: var(--app-blend-ink);
  position: relative;
  width: component.$checkbox-width;

  input {
    appearance: none;
    background: transparent;
    cursor: pointer;
    inset: 0;
    margin: 0;
    position: absolute;
  }

  .checkbox__icon {
    align-items: center;
    display: flex;
    font-size: 32px;
    justify-content: center;
    pointer-events: none;
    transition: opacity 150ms ease;

    [stroke-linecap='round'] {
      color: var(--app-field-color);
    }

    &--checked {
      display: none;
    }
  }

  input:checked ~ .checkbox__icon--checked {
    display: flex;
  }

  input:checked ~ .checkbox__icon--unchecked {
    display: none;
  }
}

@use '../../styles/utils.scss';

.choice {
  display: grid;
  grid-template-areas: var(--app-choice-areas);
  border: var(--app-field-border);
  border-radius: component.$choice-radius;
  width: 160px;
  background: transparent;
  color: inherit;
  text-align: center;
  text-decoration: none;
  padding: 8px;
  gap: component.$choice-gap;
  cursor: pointer;

  &__img {
    grid-area: choice__img;
    font-size: 3.5rem;
    color: var(--app-fg-brand);
    line-height: 1;
  }

  &__title {
    grid-area: choice__title;
    border: component.$choice-title-border-width solid var(--app-fg-default);
    padding: 8px;
    border-radius: component.$choice-title-radius;
    text-transform: uppercase;
    text-decoration: none;
    background-color: component.$choice-title-bg;
  }

  &__desc {
    grid-area: choice__desc;
  }

  @include utils.hover {
    border-color: var(--app-border-selected);

    .choice__img {
      color: component.$choice-img-fg-hover;
    }

    .choice__title {
      background-color: component.$choice-title-bg-hover;
    }
  }
}

@use '../../styles/ds/tokens' as component;

.field {
  display: flex;
  flex-direction: column;

  // The label is a TAB on top of the box, the way a section is tabbed in a
  // paper folder: it carries the box's border colour as a fill and shares its
  // top corners, so label and box read as one piece of stationery rather than
  // as two elements.
  //
  // All six of these declarations died in the migration. They read
  // `--field__label-bg`, `--field__label-color`, `--field__label-padding` and
  // three more, every one of them defined only in the variables file that was
  // deleted, and none with a fallback — so the label lost its fill, its colour,
  // its padding and its weight in a single commit.
  //
  // `check-dangling-refs` did not catch it: that guard only inspects the
  // `--app-*` namespace, and these were the old vocabulary. `check-orphan-reads`
  // exists now for exactly this class.
  &__label {
    font-weight: normal;
    border-bottom: 0;
    color: component.$field-label-fg;
    border-top-left-radius: var(--app-field-border-radius);
    border-top-right-radius: var(--app-field-border-radius);
    background-color: component.$field-label-bg;
    padding: var(--app-field-label-pad);
    align-self: flex-start;
    font-size: var(--app-field-label-font-size);
    font-family: component.$field-label-font-family;
    letter-spacing: 0.0625rem;
    mix-blend-mode: var(--app-blend-ink);
    transition: background-color var(--app-duration-base) var(--app-ease);
  }

  &__box {
    border: var(--app-field-border);
    display: flex;
    align-items: center;
    padding: calc(var(--app-field-padding) + 2px) var(--app-field-padding) 0;
    border-radius: var(--app-field-border-radius);
    border-top-left-radius: 0;
    transition: border-color 0.2s ease-in-out;
    overflow: hidden;
    position: relative;
  }

  &__bg {
    position: absolute;
    inset: 0;
    z-index: 0;
    display: flex;
    justify-content: center;
    align-items: center;
    pointer-events: none;
    opacity: 0;
    transition: opacity 0.2s ease;
    width: 80%;
    height: 100%;
    margin: auto;
    mix-blend-mode: var(--app-blend-ink);

    svg {
      height: 92%;
      width: 100%;
    }
  }

  &--bg-visible {
    .field__bg {
      opacity: 1;
    }
  }

  &__input {
    background-color: transparent;
    font-family: component.$field-input-font-family;
    font-weight: 200;
    line-height: var(--app-field-line-height);
    font-size: var(--app-field-font-size);
    color: var(--app-field-color);
    resize: none;
    width: 100%;
    border: 0;
    padding: 0;
    position: relative;
    z-index: 1;

    &::placeholder {
      color: component.$field-placeholder-fg;
      font-family: component.$field-placeholder-font-family;
      letter-spacing: 1px;
    }

    &::selection {
      color: var(--app-fg-heading);
      background: component.$field-selection-bg;
    }

    &:focus {
      outline: none;
    }
  }

  &__list {
    position: absolute;
    left: 0;
    top: 0;
    width: var(--app-field-line-height);
  }

  &__list-item {
    height: var(--app-field-line-height);
    width: var(--app-field-line-height);
    padding: 4px 3px 2px;
  }

  &__hint {
    font-family: component.$field-hint-font-family;
    margin-top: 2px;
    font-size: 13px;
  }

  &__action {
    display: flex;
    padding-left: 1rem;
  }

  &__icon {
    width: 26px;
    height: 26px;
  }

  &--list {
    .field__box {
      position: relative;
    }

    .field__input {
      padding-left: calc(var(--app-field-line-height) + 4px);
    }
  }

  &--multiline {
    .field__label {
      align-self: stretch;
      text-align: center;
    }

    .field__box {
      border-top-left-radius: 0;
      border-top-right-radius: 0;
      border: 0;
      padding: var(--app-field-box-padding-top) 0 0;
      position: relative;

      &::before {
        content: '';
        position: absolute;
        inset: var(--app-field-box-padding-top) var(--app-field-line-offset-x) 0;
        pointer-events: none;
        z-index: 0;
        background-image: repeating-linear-gradient(
          to right,
          var(--app-field-line-color) 0,
          var(--app-field-line-color) var(--app-field-line-dash-length),
          transparent var(--app-field-line-dash-length),
          transparent
            calc(var(--app-field-line-dash-length) + var(--app-field-line-dash-gap))
        );
        background-size: calc(
            var(--app-field-line-dash-length) + var(--app-field-line-dash-gap)
          )
          100%;
        background-repeat: repeat;
        /* stylelint-disable color-no-hex --
   The `#000` stops below are MASK values, not colours: a mask reads the
   alpha channel, and #000 here means "fully opaque" for the ruled line.
   No colour token can express that, and substituting one would change a
   mask into a paint. */

        -webkit-mask-image: repeating-linear-gradient(
          to bottom,
          transparent 0,
          transparent
            calc(var(--app-field-line-offset) - var(--app-field-line-thickness)),
          #000 calc(var(--app-field-line-offset) - var(--app-field-line-thickness)),
          #000 var(--app-field-line-offset),
          transparent var(--app-field-line-offset),
          transparent var(--app-field-line-step)
        );
        -webkit-mask-size: 100% var(--app-field-line-step);
        -webkit-mask-repeat: repeat;
        mask-image: repeating-linear-gradient(
          to bottom,
          transparent 0,
          transparent
            calc(var(--app-field-line-offset) - var(--app-field-line-thickness)),
          #000 calc(var(--app-field-line-offset) - var(--app-field-line-thickness)),
          #000 var(--app-field-line-offset),
          transparent var(--app-field-line-offset),
          transparent var(--app-field-line-step)
        );
        mask-size: 100% var(--app-field-line-step);
        mask-repeat: repeat;
      }
    }

    .field__input {
      background: transparent;
      position: relative;
      z-index: 1;
    }

    // Three more declarations that wrote the old name while the reader had
    // moved to `--app-*`. The large variant has not been changing its padding
    // or its rule spacing since the migration — it only looked like it was.
    &.field--large {
      .field__box {
        --app-field-box-padding-top: 24px;

        padding-top: var(--app-field-box-padding-top);
      }

      .field__input {
        --app-field-line-step: 44px;
        --app-field-line-offset: calc(
          32px - var(--app-field-line-offset-adjust)
        );

        line-height: 44px;
        font-size: 25px;
      }
    }
  }

  // A field being edited is a field the user has CHOSEN, so the whole focused
  // state comes from the `selected` family — box border, label fill, and the
  // ruled lines of a textarea together.
  &--focused {
    .field__box {
      border-color: var(--app-border-selected);
    }

    // The label inverts: the tab fills with cocoa and its text goes to the
    // measured pair, so the section you are writing in is the one that stands
    // out on the page.
    .field__label {
      color: component.$field-label-fg-focus;
      background-color: component.$field-label-bg-focus;
    }

    // The rule lines follow the focus, which is the detail that makes a
    // textarea read as the page you are writing on rather than a box near it.
    //
    // This line said `--field-line-color` while the gradient that draws the
    // rules reads `--app-field-line-color`. The migration renamed every READ
    // and left the DECLARATIONS alone, so the focus state has been writing to a
    // name nothing consumes — the lines simply stopped changing colour.
    &.field--multiline {
      --app-field-line-color: var(--app-border-selected);
    }
  }

  &--no-label {
    .field__box {
      border-radius: var(--app-field-border-radius);
    }
  }

  &--no-breakline {
    .field__box {
      padding: var(--app-field-padding);
    }
  }
}
/* stylelint-enable color-no-hex */

﻿.footer {
  background-color: component.$footer-bg;
  color: component.$footer-fg;
  bottom: 0;
  height: component.$footer-height;
  overflow: hidden;
  position: sticky;
  border-top-left-radius: component.$footer-radius;
  border-top-right-radius: component.$footer-radius;
  box-shadow: component.$footer-shadow;

  &__control {
    align-items: center;
    display: inline-flex;
    flex: 1;
    height: 100%;
    justify-content: center;
    line-height: 1;
  }

  &__navigation {
    background-color: component.$footer-navigation-bg;
    color: component.$footer-navigation-fg;
    display: flex;
    height: 100%;
    justify-content: center;
    padding: 0 16px;
  }

  &--menu {
    padding: 16px;
    transition: background-color 300ms;
    height: initial;

    &::before {
      content: '';
      display: block;
      max-width: 28px;
      height: 4px;
      border-radius: 2px;
      background-color: component.$footer-strip-bg;
      margin: 8px auto 22px;
    }
  }

  &--open {
    background-color: component.$footer-bg-open;
  }
}

.intro {
  padding-bottom: 32px;
  padding-top: 32px;
  display: grid;
  gap: component.$intro-gap;
}

@mixin notebook-tabs-container {
  display: flex;

  .notebook-tabs {
    position: sticky;
    top: 0;
    align-self: flex-start;
    height: calc(100vh - var(--app-bar-size));
    display: flex;
    flex-direction: column;
    justify-content: center;
  }

  &__content {
    flex: 1;
  }
}

.notebook-tabs-container-mobile {
  @media (orientation: portrait) {
    @include notebook-tabs-container;
  }
}

.notebook-tabs-container {
  @include notebook-tabs-container;

  @media (orientation: landscape) {
    flex-direction: row-reverse;

    .notebook-tabs {
      transform: translateX(1px);
      width: 0;
    }

    &__content {
      background-color: component.$notebook-tabs-content-bg;
    color: var(--app-fg-default);

      z-index: 1;
      // box-shadow: var(--app-shadow-raised);
    }
  }
}

@use '../../styles/helpers/media.scss' as *;
@use '../../styles/utils.scss' as *;

.notebook-tabs {
  text-transform: uppercase;
  font-size: 0.75rem;
  text-orientation: upright;
  z-index: 1;
  letter-spacing: -1px;
  line-height: 1;

  ul {
    list-style: none;
    display: grid;
    gap: 8px;
  }

  a {
    writing-mode: vertical-lr;
    background-color: component.$notebook-tabs-bg;
    border-bottom-right-radius: component.$notebook-tabs-radius;
    border-top-right-radius: component.$notebook-tabs-radius;
    box-shadow: component.$notebook-tabs-shadow;
    padding: 8px 5px 12px 3px;

    &.ovo-active {
      background-color: component.$notebook-tabs-bg-active;
      color: component.$notebook-tabs-fg-active;
      font-weight: bold;
    }
  }
}

.radio-button {
  align-items: center;
  color: var(--app-field-color);
  display: inline-flex;
  height: component.$radio-button-height;
  justify-content: center;
  line-height: 1;
  mix-blend-mode: var(--app-blend-ink);
  position: relative;
  width: component.$radio-button-width;

  input {
    appearance: none;
    background: transparent;
    cursor: pointer;
    inset: 0;
    margin: 0;
    position: absolute;
  }

  .radio-button__icon {
    align-items: center;
    display: flex;
    font-size: 24px;
    justify-content: center;
    pointer-events: none;
    transition: opacity 150ms ease;

    [stroke-linecap='round'] {
      color: var(--app-field-color);
    }

    &--checked {
      display: none;
    }
  }

  input:checked ~ .radio-button__icon--checked {
    display: flex;
  }

  input:checked ~ .radio-button__icon--unchecked {
    display: none;
  }
}

// =============================================================================
// SECTION CARD
// =============================================================================
//
// A titled panel: a brand band across the top, a paper body under it.
//
// -----------------------------------------------------------------------------
// THE BUG THIS FILE CARRIED
// -----------------------------------------------------------------------------
//
// Four of its six declarations were written like this:
//
//     background-color: var(--section-card-body-bg, --color-white);
//                                                   ^^^^^^^^^^^^^ not a value
//
// A `var()` fallback has to be a VALUE. `--color-white` there is a bare custom
// property NAME — it needed `var(--color-white)` — so the whole declaration was
// invalid and the browser dropped it. The panel fell back to whatever the
// element inherited, which is why the body looked white and the border was
// missing entirely.
//
// It reads as a decision. It compiles. Nothing warns. And it survived a full
// migration because a token that resolves to nothing and a token whose fallback
// is malformed look identical from the outside — both simply have no effect.
//
// `scripts/check-fallback-values.mjs` now fails the build on the pattern.
// =============================================================================

.section-card {
  border-radius: var(--app-card-border-radius);
  overflow: hidden;
  box-shadow: component.$section-card-shadow;
  border: component.$section-card-border-color;

  // The band. `bg-brand` and `fg-on-brand` are a measured pair, so the title is
  // legible by construction rather than by inspection.
  &__title {
    background-color: component.$section-card-title-bg;
    color: component.$section-card-title-fg;
    padding: 0 var(--app-pad-surface);
    margin: 0;
    font-size: component.$section-card-title-font-size;
    display: block;

    > * {
      padding: var(--app-pad-surface) 0;
      border-bottom: component.$section-card-title-border-width dotted component.$section-card-title-divider-color;
    }
  }

  &__body {
    padding: var(--app-pad-surface);
    background-color: component.$section-card-body-bg;
  }
}

.tabs {
  .tabs__input {
    appearance: none;
    position: absolute;
    cursor: pointer;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
  }

  .tabs__input:checked + .tabs__tab {
    background-color: component.$tabs-tab-bg-selected;
    color: component.$tabs-tab-fg-selected;
    box-shadow: component.$tabs-tab-shadow-selected;
  }

  .tabs__input:focus-visible + .tabs__tab {
    outline: var(--app-field-border);
    outline-offset: -2px;
  }

  .tabs__input:disabled + .tabs__tab {
    cursor: not-allowed;
    opacity: 0.5;
  }

  .nav-pills {
    border: component.$tabs-border-color;
    border-radius: component.$tabs-radius;
    padding: 4px;
    background: component.$tabs-bg;
  }

  .nav-link {
    position: relative;
  }
}

@use '../../styles/helpers/media.scss' as *;
@use '../../styles/utils.scss' as *;

.tabs-layout__mobile {
  @extend .portrait-only;
}

.tabs-layout__desktop {
  @extend .landscape-only;
}

.tabs-layout__content {
  width: 100%;
}

.tabs-layout__section {
  display: grid;
}

@media (orientation: portrait) {
  .tabs-layout__content {
    padding-left: var(--app-pad-surface);
    padding-right: var(--app-pad-surface);
  }
}

@media (orientation: landscape) {
  .tabs-layout__content {
    background-color: component.$tabs-layout-content-bg;
    color: var(--app-fg-default);
    // box-shadow: var(--app-shadow-raised);
    height: 100%;
    position: relative;

    &::before {
      // it hides tabs shadow
      content: '';
      position: absolute;
      left: 0;
      top: 0;
      width: 100%;
      height: 4px;
      background-color: inherit;
    }
  }

  .tabs-layout__section[data-tabs-layout-active='false'] {
    display: none;
  }
}

.card {
  container-type: inline-size;

  &__content {
    border-radius: component.$card-content-radius;
    display: grid;
    overflow: hidden;
  }

  &__img {
    grid-area: card__img;
    display: flex;
    flex-direction: column;

    img {
      background-color: component.$card-img-bg;
    }
  }

  &__header {
    grid-area: card__header;
  }

  &__footer {
    grid-area: card__footer;
  }
}

.card:not(.slim-card) {
  .card__content {
    background-color: component.$card-content-bg;
    color: var(--app-fg-default);

    box-shadow: component.$card-content-shadow;
    border: component.$card-content-border-color;
    border-radius: var(--app-card-border-radius);

    grid-template-areas:
      'card__header card__header'
      'card__img card__body'
      'card__footer card__footer';
    grid-template-columns: 7fr 10fr;
    grid-template-columns: min(200px, calc(100% * 7 / 21)) 1fr;
    grid-template-rows: 1fr auto auto;
  }

  .card__img {
    padding: 14px 0 14px var(--app-pad-surface);
    gap: calc(var(--app-pad-surface) / 2);

    img {
      // box-shadow: var(--app-shadow-raised);
    }
  }

  .card__img-description {
    font-size: 0.9375em;
    font-weight: bold;
    text-align: center;
  }

  // A card's header sits one step down from its body, which is how printed
  // matter behaves: the same paper, slightly in shadow.
  //
  // Its text read `fg-selected` — correct-looking and wrong. A header is not a
  // selected thing; it is a heading, and it only looked right because the brand
  // hue and the selection hue are the same colour in this theme.
  .card__header {
    background-color: component.$card-header-bg;
    color: var(--app-fg-heading);
    font-weight: bold;
  }

  .card__title {
    padding: component.$card-title-pad var(--app-pad-surface);
    grid-column: 2;
    font-family: component.$card-title-font-family;
    font-size: 1rem;
  }

  .card__body {
    grid-area: card__body;
    padding: component.$card-body-pad var(--app-pad-surface);
    align-self: center;
    color: var(--app-fg-default);
  }

  .card__footer {
    background-color: component.$card-footer-bg;
    color: var(--app-fg-default);

    border-top: component.$card-footer-border-color;
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    padding: component.$card-footer-pad var(--app-pad-surface);
    justify-content: flex-end;
  }

  @container (min-width: 280px) {
    .card__header {
      grid-template-columns: subgrid;
      grid-column: 1 / -1;
      display: grid;
    }

    .card__img {
      margin-top: -30px;
    }
  }
}

.slim-card {
  padding: 8px;
  border: component.$card-border-width solid component.$card-border-color;
  grid-template-areas:
    'card__img'
    'card__header'
    'card__body'
    'card_footer';
  grid-template-rows: auto auto 1fr auto;

  .card__title {
    font-weight: bold;
    padding: 8px 0;
    text-align: center;
    text-decoration: underline;
  }
}

.heading {
  display: grid;
  grid-template-areas:
    'heading__title . heading__indicator'
    'heading__subtitle . heading__indicator';
  flex-shrink: 0;
  min-height: component.$heading-min-height;
  padding: 8px;
  grid-template-columns: auto 1fr auto;
  align-items: center;

  h1,
  h2,
  h3 {
    grid-area: heading__title;
  }

  p {
    grid-area: heading__subtitle;
  }

  &__indicator {
    grid-area: heading__indicator;
  }
}

.img {
  border-radius: 1px;
}

.img-primary {
  @extend .img;

