  // transform: rotate(0.5deg);
}

.bx,
ion-icon,
.svg-icon {
  user-select: none;
  width: component.$img-width;
  height: component.$img-height;
  display: inline-block;
  fill: currentcolor;
  flex-shrink: 0;
  transition: fill 200ms cubic-bezier(0.4, 0, 0.2, 1) 0ms;
  font-size: component.$img-font-size;

  &.large {
    --icon-size: 2.25rem;
  }
}

.logo {
  width: calc(var(--app-bar-size) - var(--app-pad-surface));
}

@use '../utils.scss';

.modal {
  box-shadow: component.$modal-shadow;
  border-radius: component.$modal-radius;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  max-height: 100%;
  min-height: 0;

  &__body {
    flex: 1 1 auto;
    min-height: 0;
    overflow-x: hidden;
    overflow-y: auto;
    padding: 8px;
    padding-bottom: calc(
      8px + max(var(--dialog-keyboard-inset, 0px), env(safe-area-inset-bottom))
    );
    font-size: 1rem;
    /* iOS momentum scroll */
    -webkit-overflow-scrolling: touch;
    scroll-padding-bottom: calc(24px + var(--dialog-keyboard-inset, 0px));
    /* Opcional: melhora toque em iOS em alguns casos */
    touch-action: pan-y;
  }

  &__footer {
    align-items: center;
    display: flex;
    flex: 0 0 auto;
    gap: 8px;
    justify-content: flex-end;
    min-height: component.$modal-footer-min-height;
    padding: 8px;
    flex-shrink: 0;
  }

  @include utils.isMobile {
    width: calc(100vw - 8px);
  }

  @include utils.isDesktop {
    box-shadow: component.$modal-dialog-shadow;
    border: component.$modal-border-color;
  }
}

@use '../ds/tokens' as component;

.progressbar {
  appearance: none;
  width: 100%;
  height: 8px;
  overflow: hidden;

  // Layer 3 first, layer 2 as the fallback. The component tokens are not
  // emitted, so the chain is what makes these resolve — written out by hand
  // because this is plain CSS with no access to `component.ref-chain()`.
  border-radius: component.$progress-radius;
  background-color: component.$progress-track-bg;
  border: component.$progressbar-border-width solid var(--app-border-color);

  &::-webkit-progress-bar {
    background-color: inherit;
    border-radius: inherit;
  }

  // The filled part reports how far along something is — it is an INDICATOR,
  // not a control, so it takes neither `selected` (nothing here was chosen) nor
  // a status colour (nothing has succeeded or failed yet). `progress-fill-bg`
  // resolves to the action colour, which is the product's "the system is
  // working" hue.
  &::-webkit-progress-value {
    background-color: component.$progress-fill-bg;
    border-radius: inherit;
    transition: width var(--app-duration-base) var(--app-ease);
  }

  &::-moz-progress-bar {
    background-color: component.$progress-fill-bg;
    border-radius: inherit;
    transition: width var(--app-duration-base) var(--app-ease);
  }
}

@use '../ds/tokens' as component;

.table-container {
  background: component.$table-container-bg;
  border: component.$table-container-border-width solid
    component.$table-border-color;
  border-radius: component.$table-container-radius;
  box-shadow: none;
  max-width: 100%;
  overflow-x: auto;
  width: 100%;

  &--light {
    --table-container-bg: var(--app-bg-surface);
    --table-container-border: var(--app-border-width) solid
      component.$table-border-color;
    --table-container-shadow: none;
  }
}

.table {
  border-collapse: collapse;
  border-spacing: 0;
  color: component.$table-fg;
  font-family: component.$table-container-font-family;
  font-size: 15px;
  line-height: 1.35;
  min-width: 100%;
  overflow: hidden;
  table-layout: fixed;
  text-align: left;
  width: 100%;

  &__caption {
    background: transparent;
    border-top-left-radius: 0;
    border-top-right-radius: 0;
    color: component.$table-header-fg;
    font-family: component.$table-container-caption-font-family;
    font-size: 19px;
    mix-blend-mode: var(--table-caption-mix-blend-mode);
    padding: 11px 14px;
    text-align: center;
  }

  &__th {
    border-bottom-width: 0.5px;
    font-weight: bold;
  }

  &__td {
    border-bottom-width: 0.5px;
    font-weight: normal;
  }

  &__th,
  &__td {
    border-color: component.$table-border-color;
    border-style: solid;
    border-width: 0 0 0.5px;
    height: 44px;
    padding: 8px 6px;
    vertical-align: middle;
  }

  &__td--mono {
    color: var(--app-fg-muted);
    font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, 'Liberation Mono', 'Courier New', monospace;
  }

  &__td--accent {
    color: var(--app-fg-brand);
  }

  &__td--section {
    background: component.$table-header-bg;
    color: component.$table-header-fg;
    font-family: component.$table-container-td--section-font-family;
    font-weight: 600;
    padding: 8px;
  }

  &__tr:last-child .table__td {
    border-bottom-width: 0;
  }

  &--on-light,
  .table-container--light & {
    --table-cell-padding-inline: 3px;
    --table-head-border-width: 1.5px;
    --table-caption-font-size: 17px;
    --table-caption-padding: 7px 14px;
    --table-caption-border-radius: var(--app-radius-control-sm);
    --table-caption-bg: var(--app-bg-brand);
    --table-caption-color: var(--app-fg-on-brand);
    --table-caption-mix-blend-mode: var(--app-blend-ink);
  }

  &--on-light .table__tr:last-child .table__td,
  .table-container--light & .table__tr:last-child .table__td {
    border-bottom-width: 0.5px;
  }
}
